#nullable enable // autogenerated

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Cysharp.Threading.Tasks;
using MVZ2.IO;
using MVZ2.Managers;
using MVZ2.Resources;
using MVZ2.Sprites;
using MVZ2Logic.Resources;
using Newtonsoft.Json;
using NGettext;
using PVZEngine;
using PVZEngine.Tools.Unity;
using UnityEngine;

namespace MVZ2.ResourcePacks
{
    public class ResourcePackReaderV1 : ResourcePackReader
    {
        public ResourcePackReaderV1(MainManager main) : base(main)
        {
        }
        public override async UniTask<ResourcePack?> ReadPack(ResourceLoader loader, string key)
        {
            try
            {
                var packReadData = await UniTask.RunOnThreadPool(() => ReadPackData(loader, key));
                if (packReadData == null)
                    return null;
                var pack = new ResourcePack(key, loader.FileName);

                await UniTask.SwitchToMainThread();

                await ApplyReadData(loader, pack, packReadData);

                return pack;
            }
            catch (Exception e)
            {
                Debug.LogError($"读取语言包{key}失败：{e}");
                return null;
            }
        }
        private async UniTask<PackReadData> ReadPackData(ResourceLoader loader, string key)
        {
            // 新建一个资源包实例。
            var packData = new PackReadData(key);

            // 将manifest读取到内存。
            var localization = await LoadManifest<ResourcePackLocalization>(loader, LOCALIZATION_MANIFEST_FILENAME);
            if (localization != null)
            {
                // 加载翻译文件。
                await ReadPackCatalogsFromManifest(loader, localization, packData);
            }

            var textures = await LoadManifest<ResourcePackTextures>(loader, TEXTURE_MANIFEST_FILENAME);
            if (textures != null)
            {
                // 加载贴图。
                ReadPackSpritesFromManifest(loader, textures, packData);
            }

            var audios = await LoadManifest<ResourcePackAudiosV1>(loader, AUDIOS_MANIFEST_FILENAME);
            if (audios != null)
            {
                // 加载音效。
                ReadPackAudioClipsFromManifest(loader, audios, packData);
                ReadPackSoundsFromManifest(loader, audios, packData);
                ReadPackMusicFromManifest(loader, audios, packData);
            }

            var fragments = await LoadManifest<ResourcePackFragmentsV1>(loader, FRAGMENT_MANIFEST_FILENAME);
            if (fragments != null)
            {
                // 加载碎片。
                ReadPackFragmentFromManifest(loader, fragments, packData);
            }

            var characters = await LoadManifest<ResourcePackCharactersV1>(loader, CHARACTERS_MANIFEST_FILENAME);
            if (characters != null)
            {
                // 加载人物。
                ReadPackCharacterModificationsFromManifest(loader, characters, packData);
            }
            return packData;
        }
        private async UniTask<T?> LoadManifest<T>(ResourceLoader loader, string path)
        {
            // 加载Sprite Manifest文件。
            var manifestJson = await loader.LoadStringAsync(path);
            if (string.IsNullOrEmpty(manifestJson))
                return default;

            return JsonConvert.DeserializeObject<T>(manifestJson);
        }
        private async UniTask ReadPackCatalogsFromManifest(ResourceLoader loader, ResourcePackLocalization manifest, PackReadData packData)
        {
            if (manifest.languages == null)
                return;
            foreach (var language in manifest.languages)
            {
                // 语言代码。
                var code = language.code;
                if (string.IsNullOrEmpty(code))
                    continue;

                var catalogDictionary = new Dictionary<string, Catalog>();
                if (language.catalogs != null)
                {
                    foreach (var relativePath in language.catalogs)
                    {
                        // 获取catalog的路径，并加载。
                        var catalogPath = Path.Combine("assets", relativePath);
                        var catalog = await loader.LoadCatalogAsync(catalogPath, code);
                        if (catalog == null)
                        {
                            Log.LogWarning($"Missing catalog {relativePath} in resource pack {packData.Key}.");
                            continue;
                        }

                        // 将加载后的catalog注册。
                        var filenameWithoutExt = Path.GetFileNameWithoutExtension(catalogPath);
                        catalogDictionary.Add(filenameWithoutExt, catalog);
                    }
                }
                packData.catalogs.Add(code, catalogDictionary);
            }
        }
        private void ReadPackSpritesFromManifest(ResourceLoader loader, ResourcePackTextures manifest, PackReadData pack)
        {
            // 加载贴图
            if (manifest.textures == null)
                return;

            var generatedCategory = GetLanguagePackSpriteCategory(pack.Key);

            foreach (var packTexture in manifest.textures)
            {
                if (string.IsNullOrEmpty(packTexture.texture))
                {
                    Log.LogWarning($"Missing texture path in resource pack {pack.Key}.");
                    continue;
                }

                if (string.IsNullOrEmpty(packTexture.key))
                {
                    Log.LogWarning($"Missing texture key of path {packTexture.texture} in resource pack {pack.Key}.");
                    continue;
                }

                // 获取贴图路径。
                var textureID = NamespaceID.Parse(packTexture.key, Main.BuiltinNamespace);

                // 获取ID和图片标签。
                var splitTexturePaths = FileHelper.RemoveExtension(packTexture.texture).Split('/', '\\');
                string nsp, textureId;
                if (splitTexturePaths.Length > 1)
                {
                    nsp = splitTexturePaths[0];
                    textureId = string.Join("/", splitTexturePaths.Skip(1));
                }
                else
                {
                    nsp = string.Empty;
                    textureId = string.Join("/", splitTexturePaths);
                }
                SpriteHelper.ParseIDAndTags(textureId, out textureId, out var tags);

                // 加载贴图。
                var textureEntry = new TextureEntry(textureID, Path.Combine("assets", packTexture.texture))
                {
                    filterMode = (FilterMode)packTexture.filter,
                    wrapMode = (TextureWrapMode)packTexture.wrap
                };
                var slices = packTexture.slices;
                if (slices != null)
                {
                    for (int i = 0; i < slices.Length; i++)
                    {
                        var slice = slices[i];
                        var sliceKey = slice.key;
                        SpriteReference? spriteRef = null;
                        if (sliceKey != null && SpriteReference.TryParse(sliceKey, Main.BuiltinNamespace, out var sprRef))
                        {
                            spriteRef = sprRef;
                        }
                        if (spriteRef == null)
                        {
                            spriteRef = new SpriteReference(textureID, i);
                        }
                        var spriteKey = new SpriteLookupKey(spriteRef, slice.tags ?? tags);
                        var sliceData = new SliceData(spriteKey)
                        {
                            border = new Vector4(slice.borderLeft, slice.borderBottom, slice.borderRight, slice.borderTop),
                            extrude = 0,
                            meshType = slice.fullRect ? SpriteMeshType.FullRect : SpriteMeshType.Tight,
                            pivot = new Vector2(slice.pivotX, slice.pivotY),
                            pixelsPerUnit = 100,
                            rect = new Rect(slice.x, slice.y, slice.width, slice.height),
                            single = slice.single,
                            spriteKey = spriteKey,
                        };
                        textureEntry.slices.Add(sliceData);
                    }
                }
                pack.textureEntries.Add(textureEntry);
            }
        }
        private void ReadPackAudioClipsFromManifest(ResourceLoader loader, ResourcePackAudiosV1 audios, PackReadData pack)
        {
            if (audios.samples == null)
                return;
            foreach (var sample in audios.samples)
            {
                if (string.IsNullOrEmpty(sample.id) || !NamespaceID.TryParse(sample.id, Main.BuiltinNamespace, out var id))
                {
                    Log.LogWarning($"Incorrect property \"id\" {sample.id} of audio clip in resource pack {pack.Key}.");
                    continue;
                }
                var path = Path.Combine("assets", sample.path);
                if (string.IsNullOrEmpty(path) || !loader.Exists(path))
                {
                    Log.LogWarning($"Missing audio clip {path} in resource pack {pack.Key}.");
                    continue;
                }

                pack.audioClips.Add(id, new AudioClipEntry(path, sample.streaming));
            }
        }
        private void ReadPackSoundsFromManifest(ResourceLoader loader, ResourcePackAudiosV1 audios, PackReadData pack)
        {
            if (audios.sounds == null)
                return;
            foreach (var sound in audios.sounds)
            {
                if (sound == null)
                    continue;
                if (string.IsNullOrEmpty(sound.id) || !NamespaceID.TryParse(sound.id, Main.BuiltinNamespace, out var id))
                {
                    Log.LogWarning($"Incorrect property \"id\" {sound.id} of sound in resource pack {pack.Key}.");
                    continue;
                }
                if (sound.samples == null || sound.samples.Length <= 0)
                {
                    Log.LogWarning($"Sound {sound.id} in resource pack {pack.Key} has no samples.");
                    continue;
                }
                var samples = new List<ResourcePackSoundSample>();
                for (int i = 0; i < sound.samples.Length; i++)
                {
                    var sampleV1 = sound.samples[i];
                    if (string.IsNullOrEmpty(sampleV1.id) || !NamespaceID.TryParse(sampleV1.id, Main.BuiltinNamespace, out var sampleID))
                    {
                        Log.LogWarning($"Incorrect property \"id\" {sampleV1.id} of sound sample in resource pack {pack.Key}.");
                        continue;
                    }
                    samples.Add(new ResourcePackSoundSample(sampleID, sampleV1.weight));
                }
                var meta = new ResourcePackSoundSource(samples.ToArray())
                {
                    maxCount = sound.maxCount,
                    priority = sound.priority,
                    loopFadeInSpeed = sound.loopFadeInSpeed,
                    loopFadeOutSpeed = sound.loopFadeOutSpeed,
                    loopPitchEnd = sound.loopPitchEnd,
                    loopPitchStart = sound.loopPitchStart,
                    loopVolume = sound.loopVolume,
                };
                pack.sounds.Add(id, meta);
            }
        }
        private void ReadPackMusicFromManifest(ResourceLoader loader, ResourcePackAudiosV1 audios, PackReadData pack)
        {
            if (audios.musictracks == null)
                return;
            foreach (var track in audios.musictracks)
            {
                if (track == null)
                    continue;
                if (string.IsNullOrEmpty(track.id) || !NamespaceID.TryParse(track.id, Main.BuiltinNamespace, out var id))
                {
                    Log.LogWarning($"Incorrect property \"id\" {track.id} of music track in resource pack {pack.Key}.");
                    continue;
                }
                if (track.mainTrack == null || !NamespaceID.TryParse(track.mainTrack, Main.BuiltinNamespace, out var mainTrackID))
                {
                    Log.LogWarning($"Music {track.id} in resource pack {pack.Key} has invalid main track.");
                    continue;
                }
                NamespaceID? subTrackID = null;
                if (track.subTrack != null && NamespaceID.TryParse(track.subTrack, Main.BuiltinNamespace, out var subTrack))
                {
                    subTrackID = subTrack;
                }
                var meta = new ResourcePackMusicSource(mainTrackID, subTrackID);
                pack.musictracks.Add(id, meta);
            }
        }
        private void ReadPackFragmentFromManifest(ResourceLoader loader, ResourcePackFragmentsV1 fragments, PackReadData pack)
        {
            if (fragments.fragments == null)
                return;
            foreach (var fragment in fragments.fragments)
            {
                if (fragment == null)
                    continue;
                if (string.IsNullOrEmpty(fragment.id) || !NamespaceID.TryParse(fragment.id, Main.BuiltinNamespace, out var id))
                {
                    Log.LogWarning($"Incorrect property \"id\" {fragment.id} of fragment in resource pack {pack.Key}.");
                    continue;
                }

                bool blend = fragment.blend;

                GradientColorKey[] colorKeys;
                var colorKeysNode = fragment.colorKeys;
                if (colorKeysNode == null || colorKeysNode.Length <= 0)
                {
                    colorKeys = new GradientColorKey[]
                    {
                        new GradientColorKey(Color.magenta, 0),
                        new GradientColorKey(Color.black, 0.5f),
                    };
                }
                else
                {
                    colorKeys = new GradientColorKey[colorKeysNode.Length];
                    for (int i = 0; i < colorKeys.Length; i++)
                    {
                        var colorKeyNode = colorKeysNode[i];
                        if (colorKeyNode == null)
                            continue;
                        var col = ColorUtility.TryParseHtmlString(colorKeyNode.code, out var color) ? color : Color.magenta;
                        var time = colorKeyNode.time;
                        colorKeys[i] = new GradientColorKey(col, time);
                    }
                }

                GradientAlphaKey[] alphaKeys;
                var alphaKeysNode = fragment.alphaKeys;
                if (alphaKeysNode == null || alphaKeysNode.Length <= 0)
                {
                    alphaKeys = new GradientAlphaKey[]
                    {
                        new GradientAlphaKey(1, 0)
                    };
                }
                else
                {
                    alphaKeys = new GradientAlphaKey[alphaKeysNode.Length];
                    for (int i = 0; i < alphaKeys.Length; i++)
                    {
                        var alphaKeyNode = alphaKeysNode[i];
                        if (alphaKeyNode == null)
                            continue;
                        var alpha = alphaKeyNode.alpha;
                        var time = alphaKeyNode.time;
                        alphaKeys[i] = new GradientAlphaKey(alpha, time);
                    }
                }

                var gradient = new Gradient()
                {
                    mode = blend ? GradientMode.Blend : GradientMode.Fixed,
                    colorKeys = colorKeys,
                    alphaKeys = alphaKeys
                };

                var meta = new ResourcePackFragmentSource(gradient);
                pack.fragments.Add(id, meta);
            }
        }
        private void ReadPackCharacterModificationsFromManifest(ResourceLoader loader, ResourcePackCharactersV1 characters, PackReadData pack)
        {
            if (characters.characters == null)
                return;
            foreach (var character in characters.characters)
            {
                if (character == null)
                    continue;
                if (string.IsNullOrEmpty(character.id) || !NamespaceID.TryParse(character.id, Main.BuiltinNamespace, out var charID))
                {
                    Log.LogWarning($"Incorrect property \"id\" {character.id} of character in resource pack {pack.Key}.");
                    continue;
                }

                var variants = ReadPackCharacterModificationVariantsFromManifest(character, pack);
                var modification = new ResourcePackCharacterModification(variants)
                {
                    FaceRight = character.faceRight
                };
                pack.characterModifications.Add(charID, modification);
            }
        }
        private ResourcePackCharacterModificationVariant[] ReadPackCharacterModificationVariantsFromManifest(ResourcePackCharacterV1 character, PackReadData pack)
        {
            var variants = new List<ResourcePackCharacterModificationVariant>();
            if (character.variants != null)
            {
                foreach (var packVariant in character.variants)
                {
                    if (packVariant == null)
                        continue;
                    if (string.IsNullOrEmpty(packVariant.id) || !NamespaceID.TryParse(packVariant.id, Main.BuiltinNamespace, out var variantID))
                    {
                        Log.LogWarning($"Incorrect property \"id\" {packVariant.id} of character variant in resource pack {pack.Key}.");
                        continue;
                    }

                    ResourcePackCharacterModificationLayer[]? layers = ReadPackCharacterModificationLayersFromManifest(packVariant, pack);

                    var variant = new ResourcePackCharacterModificationVariant(variantID)
                    {
                        Width = packVariant.width,
                        Height = packVariant.height,
                        PivotX = packVariant.pivotX,
                        PivotY = packVariant.pivotY,
                        ExtendLeft = packVariant.extendLeft,
                        ExtendRight = packVariant.extendRight,
                        Layers = layers,
                    };
                    variants.Add(variant);
                }
            }
            return variants.ToArray();
        }
        private ResourcePackCharacterModificationLayer[]? ReadPackCharacterModificationLayersFromManifest(ResourcePackCharacterVariantV1 packVariant, PackReadData pack)
        {
            if (packVariant.layers == null)
                return null;
            var layerList = new List<ResourcePackCharacterModificationLayer>();
            foreach (var packLayer in packVariant.layers)
            {
                if (packLayer == null)
                    continue;
                if (string.IsNullOrEmpty(packLayer.sprite) || !SpriteReference.TryParse(packLayer.sprite, Main.BuiltinNamespace, out var layerSprite))
                {
                    Log.LogWarning($"Incorrect property \"sprite\" {packLayer.sprite} of character variant layer in resource pack {pack.Key}.");
                    continue;
                }
                var layer = new ResourcePackCharacterModificationLayer(layerSprite)
                {
                    PositionX = packLayer.x,
                    PositionY = packLayer.y,
                };
                layerList.Add(layer);
            }
            return layerList.ToArray();
        }
        protected Sprite CreateSprite(Texture2D texture2D, SliceData sliceData, string generatedCategory, string generatedName)
        {
            try
            {
                Rect rect;
                if (sliceData.single)
                {
                    rect = new Rect(0, 0, texture2D.width, texture2D.height);
                }
                else
                {
                    rect = sliceData.rect;
                    rect.y = SpriteHelper.FromTopToFromBottomY(rect.y, texture2D.height, rect.height);
                }
                rect.width = Math.Min(rect.width, texture2D.width);
                rect.height = Math.Min(rect.height, texture2D.height);

                var pivot = sliceData.pivot;
                pivot.y = SpriteHelper.FromTopToFromBottomPivotY(pivot.y);
                var meshType = sliceData.meshType;
                var border = sliceData.border;
                var spr = Main.ResourceManager.CreateSprite(texture2D, rect, pivot, generatedName, border, meshType, category: generatedCategory);
                return spr;
            }
            catch (Exception e)
            {
                Debug.LogError($"An exception thrown when loading sprite {generatedName} from a language pack: {e}");
                return Main.ResourceManager.GetDefaultSpriteClone();
            }
        }
        protected async UniTask ApplyReadData(ResourceLoader loader, ResourcePack pack, PackReadData data)
        {
            ApplyReadDataCatalogs(pack, data);
            ApplyReadDataTextures(loader, pack, data);
            await ApplyReadDataAudioClips(loader, pack, data);
            ApplyReadDataSounds(loader, pack, data);
            ApplyReadDataMusictracks(loader, pack, data);
            ApplyReadDataFragments(loader, pack, data);
            ApplyReadDataCharacterModifications(loader, pack, data);
        }
        private void ApplyReadDataCatalogs(ResourcePack pack, PackReadData data)
        {
            foreach (var lang in data.catalogs.Keys)
            {
                var packCatalogs = pack.GetOrCreateLanguageCatalogs(lang);
                // 加载文本
                foreach (var pair in data.catalogs[lang])
                {
                    packCatalogs.catalogs.Add(pair.Key, pair.Value);
                }
            }
        }
        private void ApplyReadDataTextures(ResourceLoader loader, ResourcePack pack, PackReadData data)
        {
            foreach (var textureData in data.textureEntries)
            {
                var texturePath = textureData.texturePath;
                var textureID = textureData.textureID;
                // 尝试获取资源包中的这个texture对象。
                // 如果没有获取到，新建一个。
                if (!pack.TryGetTexture2D(textureID, out var texture))
                {
                    texture = ReadTexture2D(loader, texturePath, textureID.ToString());
                    if (texture == null)
                        continue;
                    texture.filterMode = textureData.filterMode;
                    texture.wrapMode = textureData.wrapMode;
                    pack.AddTexture2D(textureID, texture);
                }

                var slices = textureData.slices;
                for (int i = 0; i < slices.Count; i++)
                {
                    var slice = slices[i];
                    var sprite = CreateSprite(texture, slice, GetLanguagePackSpriteCategory(data.Key), slice.spriteKey.ToString());
                    pack.AddSprite(slice.spriteKey, sprite);
                }
            }
        }
        private async UniTask ApplyReadDataAudioClips(ResourceLoader loader, ResourcePack pack, PackReadData data)
        {
            foreach (var pair in data.audioClips)
            {
                var entry = pair.Value;
                var path = entry.path;
                var streaming = entry.streaming;
                // 加载AudioClip。
                var audioClip = await loader.LoadAudioClipAsync(path, streaming);
                if (audioClip == null)
                {
                    Log.LogWarning($"Failed to load audio clip {path} from resource pack {pack.Key}.");
                    continue;
                }
                Main.ResourceManager.AddGeneratedAudioClip(audioClip);
                pack.AddAudioClip(pair.Key, audioClip);
            }
        }
        private void ApplyReadDataSounds(ResourceLoader loader, ResourcePack pack, PackReadData data)
        {
            foreach (var pair in data.sounds)
            {
                pack.AddResourcePackSound(pair.Key, pair.Value);
            }
        }
        private void ApplyReadDataMusictracks(ResourceLoader loader, ResourcePack pack, PackReadData data)
        {
            foreach (var pair in data.musictracks)
            {
                pack.AddResourcePackMusicSource(pair.Key, pair.Value);
            }
        }
        private void ApplyReadDataFragments(ResourceLoader loader, ResourcePack pack, PackReadData data)
        {
            foreach (var pair in data.fragments)
            {
                pack.AddResourcePackFragmentSource(pair.Key, pair.Value);
            }
        }
        private void ApplyReadDataCharacterModifications(ResourceLoader loader, ResourcePack pack, PackReadData data)
        {
            foreach (var pair in data.characterModifications)
            {
                pack.AddResourcePackCharacterModification(pair.Key, pair.Value);
            }
        }
        public const string LOCALIZATION_MANIFEST_FILENAME = "localization.json";
        public const string TEXTURE_MANIFEST_FILENAME = "textures.json";
        public const string AUDIOS_MANIFEST_FILENAME = "audios.json";
        public const string FRAGMENT_MANIFEST_FILENAME = "fragments.json";
        public const string CHARACTERS_MANIFEST_FILENAME = "characters.json";
        protected class PackReadData
        {
            public string Key;
            public Dictionary<string, Dictionary<string, Catalog>> catalogs = new();
            public List<TextureEntry> textureEntries = new();
            public Dictionary<NamespaceID, AudioClipEntry> audioClips = new();
            public Dictionary<NamespaceID, ResourcePackSoundSource> sounds = new();
            public Dictionary<NamespaceID, ResourcePackMusicSource> musictracks = new();
            public Dictionary<NamespaceID, ResourcePackFragmentSource> fragments = new();
            public Dictionary<NamespaceID, ResourcePackCharacterModification> characterModifications = new();

            public PackReadData(string key)
            {
                Key = key;
            }
        }
        protected class TextureEntry
        {
            public NamespaceID textureID;
            public string texturePath;
            public FilterMode filterMode;
            public TextureWrapMode wrapMode;
            public List<SliceData> slices = new List<SliceData>();

            public TextureEntry(NamespaceID textureID, string texturePath)
            {
                this.textureID = textureID;
                this.texturePath = texturePath;
            }
        }
        protected class AudioClipEntry
        {
            public string path;
            public bool streaming;

            public AudioClipEntry(string path, bool streaming)
            {
                this.path = path;
                this.streaming = streaming;
            }
        }
        protected class SliceData
        {
            public Rect rect;
            public Vector2 pivot;
            public float pixelsPerUnit;
            public uint extrude;
            public bool single;
            public SpriteMeshType meshType;
            public Vector4 border;
            public SpriteLookupKey spriteKey;

            public SliceData(SpriteLookupKey spriteKey)
            {
                this.spriteKey = spriteKey;
            }
        }
    }
}
